public final class ActiveResourceOperationComponentSpec extends ContractNodeSpec{public static final String VARIANT="ACTIVE_RESOURCE_OPERATION";private final DisplayName operationDisplayName;private final StableId classOperationId;private final ResourceOperationSpec operation;private final CostSpec cost;private final int actionTimeTurns;public ActiveResourceOperationComponentSpec(StableId id,DisplayName name,DisplayName operationName,StableId classOperationId,ResourceOperationSpec operation,CostSpec cost,int turns){super(id,name,NodeKind.COMPONENT,VARIANT,ImplementationState.IMPLEMENTED);if(operationName==null||classOperationId==null||operation==null||cost==null||turns<1)throw new IllegalArgumentException("active resource component fields required");operationDisplayName=operationName;this.classOperationId=classOperationId;this.operation=operation;this.cost=cost;actionTimeTurns=turns;}public DisplayName operationDisplayName(){return operationDisplayName;}public StableId classOperationId(){return classOperationId;}public ResourceOperationSpec operation(){return operation;}public CostSpec cost(){return cost;}public int actionTimeTurns(){return actionTimeTurns;}@Override public ActiveResourceOperationComponentSpec withIdentity(StableId id){return new ActiveResourceOperationComponentSpec(id,displayName(),operationDisplayName,classOperationId,operation,cost,actionTimeTurns);}@Override public ActiveResourceOperationComponentSpec withDisplayName(DisplayName name){return new ActiveResourceOperationComponentSpec(id(),name,operationDisplayName,classOperationId,operation,cost,actionTimeTurns);}}
